"""Rebuild snippets/self-hosted-injection.html from src/ (CSS + JS in one paste)."""
import pathlib
root = pathlib.Path(__file__).resolve().parent.parent
css = (root / 'src/waitlist.css').read_text()
js = (root / 'src/waitlist.js').read_text()
out = ('<!-- Waitlist — self-hosted: CSS + JS in one block. Paste into Page Header or Footer\n'
       '     Code Injection in place of the CDN lines. Generated by tools/build-snippet.py. -->\n'
       f'<style>\n{css}</style>\n<script>\n{js}</script>\n')
(root / 'snippets/self-hosted-injection.html').write_text(out)
print('wrote snippets/self-hosted-injection.html', len(out), 'bytes')
